$('build-share-story')?.addEventListener('click',()=>{const f=id=>val(id);const x={challenge:f('share-challenge'),learned:f('share-learned'),learning:f('share-learning'),ai:f('share-ai'),design:f('share-design'),evidence:f('share-evidence'),testing:f('share-testing'),revision:f('share-revision'),demo:f('share-demo'),limits:f('share-limits'),next:f('share-next'),access:f('share-access')};if(!x.challenge||!x.design||!x.demo){$('share-result').innerHTML='<div class="warning-box">Add the challenge, what you built, and the focused demo before generating the outline.</div>';return}savePart('shareStory',x);const out=$('share-result');out.innerHTML=`<div class="result-summary fit-high"><div><span class="result-kicker">Learning Showcase outline</span><h3>Tell the learning-design story, then demo one meaningful interaction</h3></div></div><ol class="presentation-outline"><li><strong>The challenge</strong><p>${esc(x.challenge)}</p></li><li><strong>What we learned from people and evidence</strong><p>${esc(x.learned||'[add interview/research insight]')}</p></li><li><strong>What we learned about learning</strong><p>${esc(x.learning||'[name the learning idea your team now understands better]')}</p></li><li><strong>What we learned about AI</strong><p>${esc(x.ai||'[explain AI role, limits, verification, or why you did not use AI]')}</p></li><li><strong>Our design and why</strong><p>${esc(x.design)}</p><p><em>Evidence/learning science:</em> ${esc(x.evidence||'[add design rationale]')}</p></li><li><strong>Testing and revision</strong><p>${esc(x.testing||'[add what happened]')}</p><p><em>We changed:</em> ${esc(x.revision||'[add revision]')}</p></li><li><strong>Focused demo</strong><p>${esc(x.demo)}</p></li><li><strong>Limit + next step</strong><p>${esc(x.limits||'[name one limitation]')}</p><p>${esc(x.next||'[name next improvement]')}</p></li></ol><div class="callout-blue"><strong>Demo backup:</strong><p>${esc(x.access||'Prepare screenshots, a paper flow, or another accessible backup.')}</p></div><button class="button secondary small" id="download-share" type="button">Download presentation outline</button>`;const plain=Object.entries(x).map(([k,v])=>`${k.toUpperCase()}: ${v}`).join('\n\n');$('download-share')?.addEventListener('click',()=>download('learning-showcase-outline.txt',plain));toolSaved(out)});

