let swIndex=0,swAnswers=load().strategyWizard||{};
function optionText(q,v){if(v==='unsure')return 'I’m not sure yet';const o=(q.options||[]).find(x=>x[0]===v);return o?o[1]:v}
function renderWizardInput(q,answer,prefix){
 if(q.type==='pathcards')return `<input id="${prefix}-current" type="hidden" value="${esc(answer||'')}"><div class="visual-choice-grid build-path-wizard-cards">${q.options.map(o=>`<button type="button" class="${answer===o[0]?'is-selected':''}" data-wizard-card="${prefix}-current" data-wizard-value="${esc(o[0])}"><strong>${esc(o[1].split(' — ')[0])}</strong><span>${esc(o[1].includes(' — ')?o[1].split(' — ').slice(1).join(' — '):'')}</span></button>`).join('')}</div>${unsureControls(q,prefix)}`;
 if(q.type==='select')return `<label for="${prefix}-current">Your answer</label><select id="${prefix}-current">${q.options.map(o=>`<option value="${esc(o[0])}">${esc(o[1])}</option>`).join('')}${q.noUnsure?'':'<option value="unsure">I’m not sure yet</option>'}</select>${q.noUnsure?'':unsureControls(q,prefix)}`;
 if(q.type==='checkbox')return `<fieldset><legend>Select all that apply</legend><div class="choice-grid">${q.options.map(o=>`<label><input type="checkbox" name="${prefix}-multi" value="${esc(o[0])}" ${(answer||[]).includes(o[0])?'checked':''}> ${esc(o[1])}</label>`).join('')}</div></fieldset><div class="wizard-uncertainty"><details><summary>Help me figure this out</summary><p>${esc(q.help||q.how||'Select only what you can observe or confirm right now. Ask your advisor if you need another perspective.')}</p></details></div>`;
 return `<label for="${prefix}-current">Your answer</label><textarea id="${prefix}-current" placeholder="${esc(q.example||'')}"></textarea>${unsureControls(q,prefix)}`;
}
function getWizardValue(q,prefix){return q.type==='checkbox'?checked(`${prefix}-multi`):val(`${prefix}-current`)}
document.addEventListener('click',e=>{const card=e.target.closest('[data-wizard-card]');if(card){const input=$(card.dataset.wizardCard);if(input){input.value=card.dataset.wizardValue;card.closest('.visual-choice-grid')?.querySelectorAll('[data-wizard-card]').forEach(x=>x.classList.toggle('is-selected',x===card));input.dispatchEvent(new Event('change',{bubbles:true}));}return;}const b=e.target.closest('[data-wizard-unsure]');if(!b)return;const input=$(b.dataset.wizardUnsure);if(!input)return;if(input.tagName==='SELECT'){if([...input.options].some(o=>o.value==='unsure'))input.value='unsure';}else input.value="I'm not sure yet.";input.dispatchEvent(new Event('change',{bubbles:true}));input.focus();});
function renderStrategyWizard(){if(!$('strategy-question'))return;const q=strategyWizardQ[swIndex];$('strategy-progress-label').textContent=`Question ${swIndex+1} of ${strategyWizardQ.length}`;$('strategy-progress').max=strategyWizardQ.length;$('strategy-progress').value=swIndex+1;$('strategy-question').innerHTML=`<span class="wizard-phase-label">Find a learning strategy</span><h3>${esc(q.label)}</h3>${guidance(q)}${renderWizardInput(q,swAnswers[q.k],'strategy')}`;const input=$('strategy-current');if(input&&swAnswers[q.k])input.value=swAnswers[q.k];$('strategy-back').disabled=swIndex===0;const btn=$('strategy-wizard-form')?.querySelector('button[type=submit]');if(btn)btn.textContent=swIndex===strategyWizardQ.length-1?'Compare strategies':'Save and continue →';$('strategy-status').textContent=''}
function strategyWizardAnalysis(a){const scores={},reasons={};Object.keys(strategies).forEach(k=>{scores[k]=10;reasons[k]=[]});const add=(k,n,r)=>{scores[k]+=n;if(r)reasons[k].push(r)};const map=(obj,r)=>Object.entries(obj).forEach(([k,n])=>add(k,n,r));
 const bm={recall:{retrieval:38,elaboration:10,transfer:8},explain:{elaboration:38,comparison:15,representation:8},procedure:{worked:32,chunking:30,error:10},error:{error:40,worked:14,metacognition:12},representation:{representation:40,comparison:20,worked:8},transfer:{transfer:40,comparison:15,elaboration:12},monitor:{metacognition:42,error:8},comprehension:{comprehension:40,elaboration:14,metacognition:10}};map(bm[a.breakdown]||{},`matches the reported breakdown: ${optionText(strategyWizardQ[0],a.breakdown)}`);
 const am={recall:{retrieval:30},explain:{elaboration:28,comparison:8},compare:{comparison:32,representation:10},sequence:{chunking:28,worked:16},apply:{transfer:30,worked:8},monitor:{metacognition:34},correct:{error:34},interpret:{representation:34,comparison:10}};map(am[a.action]||{},`directly practices: ${optionText(strategyWizardQ[2],a.action)}`);
 if(a.stage==='novice')map({worked:20,chunking:14,representation:10,comprehension:8},'provides stronger initial structure');if(a.stage==='developing')map({error:14,elaboration:10,comparison:10,transfer:8},'fits a learner who can complete some parts with support');if(a.stage==='near')map({retrieval:10,metacognition:18,transfer:14,error:8},'supports consistency and independence');
 const fm={hints:{error:12,worked:12,chunking:6},explain:{elaboration:16,comparison:8},correctness:{retrieval:8,error:16},reflection:{metacognition:18,transfer:6},model:{worked:20,chunking:8}};map(fm[a.feedback]||{},`fits the selected feedback: ${optionText(strategyWizardQ[5],a.feedback)}`);
 const cm={repeated:{retrieval:14,error:8},varied:{transfer:18,comparison:8},one:{worked:8,elaboration:8,representation:8},authentic:{transfer:12,metacognition:8,chunking:6}};map(cm[a.context]||{},`fits the practice context: ${optionText(strategyWizardQ[6],a.context)}`);
 const cs=a.constraints||[];if(cs.includes('reading'))map({representation:8,chunking:5},'can reduce or reorganize reading/language demands');if(cs.includes('visual'))map({representation:10,comparison:6},'can support multiple representations');if(cs.includes('pacing'))map({metacognition:8,chunking:6,worked:5},'can support learner-controlled pacing');if(cs.includes('short'))map({retrieval:7,error:6,comparison:5},'can fit short practice windows');if(cs.includes('social'))map({elaboration:8,comparison:7,error:5},'works well through dialogue or partner interaction');
 const ranked=Object.keys(scores).map(k=>({k,score:scores[k],reasons:[...new Set(reasons[k])]})).sort((x,y)=>y.score-x.score),max=ranked[0].score;ranked.forEach(r=>r.fit=pct(55+(r.score/max)*43));const confidence={direct:'High',some:'Moderate',report:'Tentative',assumption:'Low'}[a.evidence]||'Tentative';const cautions=[];if(a.evidence==='assumption')cautions.push('Your explanation is still mostly an assumption. Collect direct evidence before committing to a strategy.');if(a.evidence==='report')cautions.push('Add a work sample, observation, or short learner task before treating the match as strong.');if(cs.includes('offline'))cautions.push('Choose a product form that still works without reliable internet.');return {top:ranked.slice(0,3),confidence,cautions};}
$('strategy-wizard-form')?.addEventListener('submit',e=>{e.preventDefault();const q=strategyWizardQ[swIndex],v=getWizardValue(q,'strategy');if((Array.isArray(v)&&!v.length)||(!Array.isArray(v)&&!v)){$('strategy-status').textContent='Add an answer before continuing.';return}swAnswers[q.k]=v;savePart('strategyWizard',swAnswers);if(swIndex<strategyWizardQ.length-1){swIndex++;renderStrategyWizard();return}const a=strategyWizardAnalysis(swAnswers);savePart('strategy',{top:a.top,inputs:swAnswers});savePart('lastStrategy',a.top[0]?.k);const out=$('strategy-results');out.innerHTML=`<div class="result-summary fit-high"><div><span class="result-kicker">Strategy confidence: ${esc(a.confidence)}</span><h3>Compare these three possibilities</h3><p>These are hypotheses to discuss with your advisor—not an automatic prescription.</p></div></div><p><strong>Your evidence:</strong> ${esc(swAnswers.evidenceNote)}</p><div class="fit-grid">${a.top.map((r,i)=>{const p=strategies[r.k];return `<article class="fit-card"><div class="fit-card-heading"><span class="fit-badge ${i===0?'fit-high':'fit-medium'}">${r.fit}% fit</span><span>#${i+1}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.desc)}</p><p><strong>Why it was suggested</strong></p>${list(r.reasons)}<p><strong>This strategy could become</strong></p>${list(p.products.slice(0,5))}<p><strong>How to test it</strong></p><p>${esc(p.test)}</p><p><strong>Watch for</strong></p><p>${esc(p.caution)}</p></article>`}).join('')}</div>${a.cautions.length?`<div class="warning-box"><strong>Evidence caution</strong>${list(a.cautions)}</div>`:''}<div class="tool-actions"><a class="button primary" href="#resource-inventor">Next: Build an activity-design prompt →</a></div>`;toolSaved(out)});
$('strategy-back')?.addEventListener('click',()=>{const q=strategyWizardQ[swIndex],v=getWizardValue(q,'strategy');if((Array.isArray(v)&&v.length)||(!Array.isArray(v)&&v))swAnswers[q.k]=v;if(swIndex>0)swIndex--;renderStrategyWizard()});renderStrategyWizard();

