let rwIndex=0,rwAnswers=load().resourcePrompt||{};
function renderResourceWizard(){if(!$('resource-question'))return;const q=resourceWizardQ[rwIndex];$('resource-progress-label').textContent=`Question ${rwIndex+1} of ${resourceWizardQ.length}`;$('resource-progress').max=resourceWizardQ.length;$('resource-progress').value=rwIndex+1;$('resource-question').innerHTML=`<span class="wizard-phase-label">Build the AI request</span><h3>${esc(q.label)}</h3>${guidance(q)}${renderWizardInput(q,rwAnswers[q.k],'resource')}`;const input=$('resource-current');if(input&&rwAnswers[q.k])input.value=rwAnswers[q.k];$('resource-back').disabled=rwIndex===0;const btn=$('resource-wizard-form')?.querySelector('button[type=submit]');if(btn)btn.textContent=rwIndex===resourceWizardQ.length-1?'Create my AI prompt':'Save and continue →';$('resource-status').textContent=''}
function buildResourcePrompt(a){const mats=(a.resources||[]).map(x=>resourceNames[x]||x);if(a.other&&a.other.toLowerCase()!=='none')mats.push(a.other);const strategy=strategies[a.strategy]?.name||a.strategy;const grouping=optionText(resourceWizardQ[4],a.participation),time=optionText(resourceWizardQ[5],a.time),variety=optionText(resourceWizardQ[7],a.variety);return `Act as a creative learning-activity design partner. Help me generate possibilities; do not decide which idea my team must use.\n\nLEARNING TARGET\nThe learner is trying to: ${a.target}\n\nLEARNING STRATEGY TO EXPLORE\nUse ${strategy}. Make the learner actively do the thinking required by this strategy rather than only receive information.\n\nRESOURCES WE ACTUALLY HAVE\n${mats.join(', ')||'No specific resources listed'}\n\nPARTICIPATION\n${grouping}\n\nTIME FOR ONE ACTIVITY\n${time}\n\nACCESS AND PRACTICAL REQUIREMENTS\n${a.access}\n\nREQUEST\nGenerate ${variety.toLowerCase()}. Make the approaches genuinely different from one another. Use our available materials, people, and spaces meaningfully rather than defaulting to a chatbot or app. When possible, include at least one low-tech/physical approach and one social or collaborative approach. AI may be used in an activity only where it adds a useful capability.\n\nFor each idea, provide:\n1. A short name and one-sentence concept.\n2. What the learner actually does, step by step.\n3. How the available resources are used.\n4. How ${strategy} is built into the activity.\n5. What feedback or self-check the learner receives after making an attempt.\n6. How support can fade or the learner can become more independent.\n7. One accessibility adaptation or alternative way to participate.\n8. The smallest version we could prototype quickly.\n9. One risk: how the activity might accidentally make the task easier without improving learning.\n\nDo not ask for identifying or sensitive learner information. Do not assume that a learner difficulty is a fixed deficit. Do not invent research citations. If you make a learning-science claim, label it as something we should verify.`}
$('resource-wizard-form')?.addEventListener('submit',e=>{e.preventDefault();const q=resourceWizardQ[rwIndex],v=getWizardValue(q,'resource');if((Array.isArray(v)&&!v.length)||(!Array.isArray(v)&&!v)){$('resource-status').textContent=q.k==='other'?'Enter “none” or describe what else is available.':'Add an answer before continuing.';return}rwAnswers[q.k]=v;savePart('resourcePrompt',rwAnswers);if(rwIndex<resourceWizardQ.length-1){rwIndex++;renderResourceWizard();return}const prompt=buildResourcePrompt(rwAnswers),res=rwAnswers.resources||[];savePart('resourceIdeas',{target:rwAnswers.target,strategy:rwAnswers.strategy,res,other:rwAnswers.other,prompt});const out=$('resource-results');out.innerHTML=`<div class="result-summary fit-high"><div><span class="result-kicker">Resource Inventor prompt</span><h3>Review this before you submit it to AI</h3><p>The AI should widen your options. Your team still decides what actually fits the learner.</p></div></div><pre class="prompt-copy-box">${esc(prompt)}</pre><div class="tool-actions"><button class="button secondary small" id="copy-resource-prompt" type="button">Copy prompt</button><button class="button secondary small" id="download-resource-prompt" type="button">Download prompt</button><a class="button primary small" href="#idea-board">Next: Turn possibilities into your own ideas →</a></div><div class="note-box"><strong>After you run it:</strong> save a few useful ideas or ingredients. In the Five-Idea Sprint, you will critique and remix them rather than copying one unchanged.</div>`;$('copy-resource-prompt')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(prompt);$('resource-status').textContent='Prompt copied.'}catch(e){$('resource-status').textContent='Copy was blocked by the browser. Select the prompt text and copy it manually.'}});$('download-resource-prompt')?.addEventListener('click',()=>download('resource-inventor-ai-prompt.txt',prompt));toolSaved(out,'Prompt saved in this browser.')});
$('resource-back')?.addEventListener('click',()=>{const q=resourceWizardQ[rwIndex],v=getWizardValue(q,'resource');if((Array.isArray(v)&&v.length)||(!Array.isArray(v)&&v))rwAnswers[q.k]=v;if(rwIndex>0)rwIndex--;renderResourceWizard()});
if(!rwAnswers.target&&load().breakdown?.frame)rwAnswers.target=load().breakdown.frame;if(!rwAnswers.strategy&&load().lastStrategy)rwAnswers.strategy=load().lastStrategy;renderResourceWizard();

// --- Five-Idea Sprint: one creative round at a time ---
const ideaRounds=[
 {name:'No AI',title:'Start without AI',prompt:'What could help the learner if you were not allowed to use AI at all?'},
 {name:'Use what you have',title:'Transform an ordinary resource',prompt:'Choose something already around you. How could the learner actively use it to practice, compare, explain, plan, or get feedback?'},
 {name:'People / social',title:'Make another person part of the interaction',prompt:'How could a partner, teacher, teammate, or role-play create useful thinking or feedback?'},
 {name:'AI-inspired',title:'Critique and remix an AI idea',prompt:'Use one possibility from Resource Inventor. What would you keep, change, simplify, or combine so it better fits the learner?'},
 {name:'Wild card',title:'Make the idea you would normally skip',prompt:'Try an unusual format, space, object, rule, or interaction. It can be strange as long as the learner still does the target thinking.'}
];
const ideaTwists=['It must work without a screen.','The learner must explain something to another person.','It must fit in five minutes.','Use only three physical materials.','The learner must make a prediction before receiving feedback.','Use movement or a school space.','Make the learner compare two cases.','Make it work with a partner and independently.','The tool cannot tell the learner whether they are right immediately.','Use something ordinary in an unexpected way.'];
