$('idea-next')?.addEventListener('click',()=>{const v=val('idea-current');if(!v){$('idea-status').textContent='Add an idea before moving on.';return}ideaAnswers[ideaIndex]=v;savePart('ideaSprint',ideaAnswers);if(ideaIndex<ideaRounds.length-1){ideaIndex++;renderIdeaRound();return}const filled=ideaRounds.map((r,i)=>[r.name,ideaAnswers[i]]);savePart('ideaBoard',filled);const out=$('idea-board-result');out.innerHTML=`<div class="result-summary fit-high"><div><span class="result-kicker">Five ideas complete</span><h3>Now choose up to two finalists</h3><p>Choose based on learner action, access, available resources, and what you can learn from a quick prototype—not technical impressiveness.</p></div></div><div class="idea-sprint-cards">${filled.map((x,i)=>`<article class="idea-sprint-card" data-idea-card="${i}"><span class="idea-sprint-round">${esc(x[0])}</span><p>${esc(x[1])}</p><button class="button ghost small" type="button" data-finalist="${i}">☆ Mark as finalist</button></article>`).join('')}</div><p class="status" id="idea-finalist-status">Select up to two finalists.</p>`;toolSaved(out)});
$('idea-back')?.addEventListener('click',()=>{const v=val('idea-current');if(v)ideaAnswers[ideaIndex]=v;if(ideaIndex>0)ideaIndex--;renderIdeaRound()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-finalist]');if(!b)return;const i=Number(b.dataset.finalist),saved=load().ideaFinalists||[],has=saved.includes(i);let next;if(has)next=saved.filter(x=>x!==i);else if(saved.length>=2){const s=$('idea-finalist-status');if(s)s.textContent='Keep the shortlist to two ideas so you can compare them seriously.';return}else next=[...saved,i];savePart('ideaFinalists',next);document.querySelectorAll('[data-idea-card]').forEach(c=>c.classList.toggle('is-finalist',next.includes(Number(c.dataset.ideaCard))));document.querySelectorAll('[data-finalist]').forEach(x=>{const on=next.includes(Number(x.dataset.finalist));x.textContent=on?'★ Finalist':'☆ Mark as finalist'});const s=$('idea-finalist-status');if(s)s.textContent=`${next.length} finalist${next.length===1?'':'s'} selected.`});renderIdeaRound();

