function renderBuildWizard(){if(!$('build-question'))return;const qs=bwPhase==='decision'?buildDecisionQ:buildProtoQ,q=qs[bwIndex],overall=(bwPhase==='decision'?bwIndex:buildDecisionQ.length+1+bwIndex)+1,total=buildDecisionQ.length+1+buildProtoQ.length;$('build-progress').max=total;$('build-progress').value=Math.min(overall,total);$('build-progress-label').textContent=bwPhase==='decision'?`Choose form · Question ${bwIndex+1} of ${buildDecisionQ.length}`:`Plan prototype · Question ${bwIndex+1} of ${buildProtoQ.length}`;$('build-question').innerHTML=`<span class="wizard-phase-label">${bwPhase==='decision'?'Part 1 · Choose a product form':'Part 2 · Plan the smallest prototype'}</span><h3>${esc(q.label)}</h3>${guidance(q)}${renderWizardInput(q,bwAnswers[q.k],'build')}`;const input=$('build-current');if(input){if(bwAnswers[q.k])input.value=bwAnswers[q.k];else if(q.k==='materials'){const rp=load().resourcePrompt,ms=(rp?.resources||[]).map(x=>resourceNames[x]||x);if(rp?.other&&rp.other.toLowerCase()!=='none')ms.push(rp.other);if(ms.length)input.value=ms.join(', ')}}$('build-back').disabled=bwPhase==='decision'&&bwIndex===0;const btn=$('build-wizard-form')?.querySelector('button[type=submit]');if(btn)btn.textContent=(bwPhase==='prototype'&&bwIndex===buildProtoQ.length-1)?'Create my prototype plan':'Save and continue →';$('build-status').textContent=''}
