function renderTests(){if(!$('test-records'))return;const history=tests.length?tests.map((r,i)=>`<article class="record-card version-record"><div class="version-node">${i+1}</div><div><span class="result-kicker">Test ${i+1}</span><h3>${esc(r.version||`Prototype ${i+1}`)}</h3><p><strong>What the learner did:</strong> ${esc(r.behavior||'')}</p><p><strong>What the learner said:</strong> ${esc(r.said||'')}</p><p><strong>Still difficult:</strong> ${esc(r.struggle||'')}</p><p><strong>Evidence about learning:</strong> ${esc(r.learning||'')}</p><p><strong>Tool/access issue:</strong> ${esc(r.confusion||'')}</p><p><strong>Did the tool/AI do too much?</strong> ${esc(({noai:'No AI in learner interaction',learner:'Learner did the important thinking',mixed:'Mixed',tooMuch:'Tool/AI did too much',unsure:'Still uncertain'})[r.aiLoad]||r.aiLoad||'')}</p><p><strong>Evidence about the thinking:</strong> ${esc(r.aiDetail||'')}</p><p><strong>Revision:</strong> ${esc(r.revision||'')}</p><div class="revision-proof"><strong>Because of testing, we changed…</strong><p>${esc(r.changed||r.revision||'')}</p></div></div></article>`).join(''):'<p class="empty-state">No test records yet. Your first completed test will begin the version history.</p>';$('test-records').innerHTML=history}
function renderTestWizard(){if(!$('test-question-area'))return;const qs=twPhase==='plan'?testPlanQ:testObserveQ,q=qs[twIndex];$('test-phase-banner').textContent=twPhase==='plan'?'Phase 1 · Start with the learning target, then plan':'Phase 2 · Record evidence, revise, and compare versions';$('test-progress-label').textContent=`Question ${twIndex+1} of ${qs.length}`;$('test-progress').max=qs.length;$('test-progress').value=twIndex+1;$('test-question-area').innerHTML=`<span class="wizard-phase-label">${twPhase==='plan'?'Before the test':'After the test'}</span><h3>${esc(q.label)}</h3>${guidance(q)}${renderWizardInput(q,twAnswers[q.k],'test')}`;const input=$('test-current');if(input&&twAnswers[q.k])input.value=twAnswers[q.k];$('test-back').disabled=twIndex===0;const btn=$('test-wizard-form')?.querySelector('button[type=submit]');if(btn)btn.textContent=twIndex===qs.length-1?(twPhase==='plan'?'Create test plan':'Save test + revision'):'Save and continue →';$('test-status').textContent=''}
$('test-wizard-form')?.addEventListener('submit',e=>{e.preventDefault();const qs=twPhase==='plan'?testPlanQ:testObserveQ,q=qs[twIndex],v=getWizardValue(q,'test');if((Array.isArray(v)&&!v.length)||(!Array.isArray(v)&&!v)){$('test-status').textContent='Add an answer before continuing.';return}twAnswers[q.k]=v;savePart('testWizard',twAnswers);if(twIndex<qs.length-1){twIndex++;renderTestWizard();return}if(twPhase==='plan'){const caut=twAnswers.who==='learner'?'Confirm advisor approval, permissions, privacy, accessibility, and the stopping rule before testing with the intended learner.':twAnswers.who==='peer'?'Peer testing can reveal clarity and interaction problems, but may not show learning for a different intended learner.':'Use this test only for claims this tester and task can actually support.';savePart('testPlan',{...twAnswers});$('test-plan-result').innerHTML=`<div class="result-summary fit-high"><div><span class="result-kicker">Focused test plan</span><h3>Test the learning target—not whether someone likes the prototype</h3><p>Run the task without coaching the answer. Observe first; explain afterward.</p></div></div><div class="synthesis-grid"><p><strong>Learning objective:</strong> ${esc(twAnswers.objective)}</p><p><strong>Evidence of success:</strong> ${esc(twAnswers.success)}</p><p><strong>Tester:</strong> ${esc(optionText(testPlanQ[2],twAnswers.who))}</p><p><strong>Test question:</strong> ${esc(twAnswers.question)}</p><p><strong>Exact task:</strong> ${esc(twAnswers.task)}</p><p><strong>Watch/listen for:</strong> ${esc(twAnswers.watch)}</p><p><strong>Pause/stop when:</strong> ${esc(twAnswers.stop)}</p></div><div class="note-box">${esc(caut)}</div>`;$('test-wizard-form').hidden=true;$('test-ran-it').hidden=false;toolSaved($('test-plan-result'));return}const r={version:twAnswers.version,behavior:twAnswers.behavior,said:twAnswers.said,struggle:twAnswers.struggle,expected:twAnswers.expected,confusion:twAnswers.confusion,learning:twAnswers.learning,aiLoad:twAnswers.aiLoad,aiDetail:twAnswers.aiDetail,revision:twAnswers.revision,changed:twAnswers.changed,objective:twAnswers.objective,success:twAnswers.success};tests.push(r);savePart('tests',tests);savePart('latestTest',{...r,index:tests.length});renderTests();$('test-plan-result').innerHTML=`<div class="result-summary fit-high"><div><span class="result-kicker">Test ${tests.length} recorded</span><h3>Evidence should change the next version</h3><p><strong>Because of testing, we changed:</strong> ${esc(r.changed)}</p></div></div><div class="tool-actions"><button class="button primary" id="test-another" type="button">Plan the next version →</button><a class="button secondary" href="student-share.html#share-builder">When the evidence is strong enough: Build the sharing story →</a></div>`;$('test-wizard-form').hidden=true;toolSaved($('test-plan-result'))});
