$('share-back')?.addEventListener('click',()=>{const q=shareQ[shIndex],v=getWizardValue(q,'share');if((Array.isArray(v)&&v.length)||(!Array.isArray(v)&&v))shAnswers[q.k]=v;if(shIndex>0)shIndex--;renderShareWizard()});renderShareWizard();

